package zone.moddev.mc.ironagearchitecture.roof;

import java.util.*;
import net.minecraft.entity.player.*;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.text.TextComponentString;
import net.minecraft.world.World;

/** Shared, revisioned drawings; the short undo history is scoped to an actively edited roof. */
public final class RoofDrafts {
    private static final Map<World,Map<UUID,History>> HISTORY=new WeakHashMap<>();
    private static final class History {final ArrayDeque<RoofPlan> undo=new ArrayDeque<>(),redo=new ArrayDeque<>();}
    private RoofDrafts(){}
    public static void upgrade(RoofPlan p){if(p.version==1){p.version=2;p.wallInset=0;p.drop=0;p.edge=0;p.overhang[0]=p.overhang[1]=p.eave;p.overhang[2]=p.overhang[3]=p.gable;}}
    public static RoofPlan read(World w,UUID id){RoofPlan p=RoofData.get(w).drawing(id);return p==null?null:RoofPlanner.solve(p.copy());}
    public static boolean near(EntityPlayer player,RoofPlan p){return player.posX>=p.minX-64&&player.posX<=p.maxX+64&&player.posZ>=p.minZ-64&&player.posZ<=p.maxZ+64&&Math.abs(player.posY-p.floorY)<64;}
    private static History history(World w,UUID id){Map<UUID,History> map=HISTORY.computeIfAbsent(w,k->new LinkedHashMap<>());if(map.size()>=64&&!map.containsKey(id))map.remove(map.keySet().iterator().next());return map.computeIfAbsent(id,k->new History());}
    public static RoofPlan accept(World w,EntityPlayer player,RoofPlan next){RoofPlan old=RoofData.get(w).drawing(next.id);if(old==null||old.revision!=next.revision||!near(player,old)||RoofConstruction.busy(w,next.id))throw new IllegalArgumentException("The drawing changed. It has been refreshed; try the edit again.");if(next.floorY!=old.floorY||next.minX<old.minX-2||next.maxX>old.maxX+2||next.minZ<old.minZ-2||next.maxZ>old.maxZ+2)throw new IllegalArgumentException("Keep clipboard edits within the detected roof.");permissions(w,player,old);History h=history(w,next.id);h.undo.addLast(old.settingsCopy());while(h.undo.size()>32)h.undo.removeFirst();h.redo.clear();upgrade(next);RoofSupports.detect(w,next);next.revision=old.revision+1;RoofPlanner.solve(next);RoofData.get(w).draft(next);return next;}
    private static void permissions(World w,EntityPlayer player,RoofPlan p){for(int x=p.minX;x<=p.maxX;x++)for(int z=p.minZ;z<=p.maxZ;z++){BlockPos at=new BlockPos(x,p.floorY,z);if(!w.isBlockLoaded(at)||!w.isBlockModifiable(player,at)||!player.canPlayerEdit(at,EnumFacing.UP,null))throw new IllegalArgumentException("You cannot change this roof drawing here.");}}
    public static RoofPlan undo(World w,EntityPlayer player,UUID id,boolean redo){RoofPlan current=read(w,id);if(current==null||!near(player,current)||RoofConstruction.busy(w,id))throw new IllegalArgumentException("This drawing is unavailable.");permissions(w,player,current);History h=history(w,id);ArrayDeque<RoofPlan> source=redo?h.redo:h.undo,target=redo?h.undo:h.redo;if(source.isEmpty())return current;target.addLast(current.settingsCopy());RoofPlan p=source.removeLast();p.revision=current.revision+1;RoofPlanner.solve(p);RoofData.get(w).draft(p);return p;}
    public static ItemStack held(EntityPlayer p,UUID id){for(ItemStack s:new ItemStack[]{p.getHeldItemMainhand(),p.getHeldItemOffhand()})if(id.equals(RoofClipboardItem.bound(s))&&s.getTagCompound().getInteger("dimension")==p.dimension)return s;return null;}
    public static void point(World w,EntityPlayer player,ItemStack stack,BlockPos at,EnumFacing face){UUID id=RoofClipboardItem.bound(stack);if(id==null||stack.getTagCompound().getInteger("dimension")!=player.dimension){player.sendStatusMessage(new TextComponentString("Link the clipboard to a workbench first."));return;}RoofPlan p=read(w,id);if(p==null||!near(player,p)||!w.isBlockLoaded(at)||!w.isBlockModifiable(player,at)||!player.canPlayerEdit(at,face,stack))return;RoofCell c=RoofData.get(w).at(w,at);if(c==null)c=p.cells.get(at.toLong());if(c==null||!c.plan.equals(id)){player.sendStatusMessage(new TextComponentString("Point at this drawing's roof or its preview."));return;}NBTTagCompound n=stack.getTagCompound();int tool=n.getInteger("tool");RoofPart hit=RoofDesignInteraction.target(w,at,player);if(hit==null){net.minecraft.util.math.Vec3d a=zone.moddev.mc.ironagearchitecture.block.SmartThatchBlock.eyes(player),look=zone.moddev.mc.ironagearchitecture.block.SmartThatchBlock.look(player).scale(6);net.minecraft.util.math.RayTraceResult ray=RoofMeshes.drawing(c).trace(at,a,a.add(look));if(ray!=null&&ray.hitInfo instanceof Integer&&((Integer)ray.hitInfo)<c.parts.size())hit=c.parts.get((Integer)ray.hitInfo);}if(hit==null){player.sendStatusMessage(new TextComponentString("Point at a surface of this roof drawing."));return;}int selected=featureId(hit.id);if(player.isSneaking()||tool==4){n.setInteger("selected",selected);RoofNetwork.replyDrawing((EntityPlayerMP)player,p,true,stack);return;}
        try{
            RoofWindow clicked=null;if(hit!=null&&hit.kind==RoofPart.WINDOW)for(RoofWindow window:c.windows)if(window.id.equals(hit.id)){clicked=window;break;}
            if(tool==5){int chosen=selected>=0?selected:n.getInteger("selected");RoofFeature original=null;for(RoofFeature f:p.features)if(f.id==chosen)original=f;if(clicked!=null&&clicked.vertical&&original!=null){RoofFeature panel=new RoofFeature();panel.id=nextId(p);panel.type=RoofFeature.SOLID_PANEL;panel.u=RoofDesignPlanner.u(p,clicked.owner);panel.v=RoofDesignPlanner.v(p,clicked.owner);panel.y=clicked.owner.getY()-((clicked.joins&zone.moddev.mc.ironagearchitecture.block.WindowGeometry.DOWN)!=0?1:0);panel.height=clicked.joins==0?1:2;panel.width=1;panel.parent=original.parent>=0?original.parent:original.id;panel.facing=clicked.facing.getHorizontalIndex();p.features.add(panel);}else p.features.removeIf(f->f.id==chosen||f.parent==chosen);
            }else if(tool==3){int u=RoofDesignPlanner.u(p,at);double mid=(p.alongX?p.minZ+p.maxZ+1:p.minX+p.maxX+1)/2.0;p.mansard^=u<mid?1:2;
            }else{RoofFeature f=n.hasKey("options")?RoofFeature.read(n.getCompoundTag("options")):new RoofFeature();f.type=tool==0?RoofFeature.WINDOW:tool==1?RoofFeature.GABLE:RoofFeature.SHED;f.id=nextId(p);f.u=RoofDesignPlanner.u(p,at);f.v=RoofDesignPlanner.v(p,at)-(f.type==RoofFeature.WINDOW?0:f.width/2);
                if(tool==0){f.width=1;f.height=Math.min(2,f.height);if(clicked!=null&&!clicked.vertical){RoofFeature old=null;for(RoofFeature a:p.features)if(a.id==selected)old=a;if(old!=null){f.id=old.id;f.u=old.u;f.v=old.v;p.features.remove(old);}}else if(selected>=0&&((hit!=null&&hit.kind==RoofPart.WALL)||clicked!=null&&clicked.vertical)){RoofFeature parent=null;for(RoofFeature a:p.features)if(a.id==selected)parent=a;if(parent!=null){f.type=RoofFeature.VERTICAL_WINDOW;f.parent=parent.parent>=0?parent.parent:parent.id;f.u=RoofDesignPlanner.u(p,clicked==null?at:clicked.owner);f.v=RoofDesignPlanner.v(p,clicked==null?at:clicked.owner);f.y=clicked==null?at.getY():clicked.owner.getY();f.facing=(clicked==null?face:clicked.facing).getHorizontalIndex();}}if(f.type==RoofFeature.WINDOW)f.height=1;}
                p.features.add(f);n.setInteger("selected",f.id);
            }
            p=accept(w,player,p);RoofNetwork.replyDrawing((EntityPlayerMP)player,p,true,stack);}catch(IllegalArgumentException e){player.sendStatusMessage(new TextComponentString(e.getMessage()));RoofNetwork.replyDrawing((EntityPlayerMP)player,read(w,id),true,stack);}
    }
    private static int nextId(RoofPlan p){int next=1;for(RoofFeature f:p.features)next=Math.max(next,f.id+1);return next;}
    public static int featureId(String id){try{String[] a=id.split(":");return a.length>1&&(a[0].equals("feature")||a[0].equals("window"))?Integer.parseInt(a[1]):-1;}catch(NumberFormatException e){return -1;}}
}
